import{_ as i,C as r,o as n,c as o,E as a,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"信任执行，不等于授权继承秘密","description":"","frontmatter":{"title":"信任执行，不等于授权继承秘密","date":"2026-08-21","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"When repository- or plugin-supplied configuration can execute a helper, how should an engineering runtime separate authority to execute code from authority to inherit ambient credentials and other host capabilities?","summary":"Workspace Trust 可以授权 Repository-controlled Helper 执行，却不必同时授予 Parent Process 继承来的所有 Credential。Claude Code v2.1.238 材料揭示了这种双门禁设计的价值与边界。","sources":["research/analysis/Q-20260821-03-execution-trust-secret-authority-separation.md"],"item_id":"Q-20260821-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-21-trust-run-not-inherit-secrets-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-08-21-trust-run-not-inherit-secrets.md","filePath":"zh/engineering/2026-08-21-trust-run-not-inherit-secrets.md","lastUpdated":1787382334000}'),l={name:"zh/engineering/2026-08-21-trust-run-not-inherit-secrets.md"};function c(d,e,u,p,h,C){const t=r("ArticleCover");return n(),o("div",null,[a(t,{image:"/assets/covers/daily-2026-08-21-trust-run-not-inherit-secrets-cover-v2.png",kicker:"开源工程 · 每日研究",title:"信任执行，不等于授权继承秘密",summary:"Workspace Trust 可以授权 Repository-controlled Helper 执行，却不必同时授予 Parent Process 继承来的所有 Credential。Claude Code v2.1.238 材料揭示了这种双门禁设计的价值与边界。",version:"Q-20260821-03",status:"Daily Runtime V5 · 2026-08-21",languageHref:"/en/engineering/2026-08-21-trust-run-not-inherit-secrets",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="信任执行-不等于授权继承秘密" tabindex="-1">信任执行，不等于授权继承秘密 <a class="header-anchor" href="#信任执行-不等于授权继承秘密" aria-label="Permalink to &quot;信任执行，不等于授权继承秘密&quot;">​</a></h1><p>MCP <code>headersHelper</code> 看起来像一个配置字段，实际值却是 Shell Command。命令会在连接时运行，输出 JSON，并可生成 Authentication Header。当 Repository、Plugin 或 Agent File 提供这个 Helper 时，加载配置已经跨越 Code-execution Boundary。代码获准执行后，Child Process 还可能继承启动 Runtime 的 Credential。这是两种不同授权。</p><p>Claude Code v2.1.238 的发布材料分别记录了两个控制。Project <code>.mcp.json</code> Helper，以及 Project 或 <code>--add-dir</code> Agent File 中的 Inline MCP Server，必须先接受相关 Folder Trust，包括 <code>claude -p</code> 场景。同一 Release Note 还声明，Project、Plugin 与 Agent-file <code>headersHelper</code> 不继承 Credential Environment Variables。官方 MCP 文档则独立确认：Helper 是 Shell Execution，输出会成为 Connection Header，并可获得 Server Name、URL 等 Purpose-specific Variable。</p><p>工程规则简单却重要：<strong>允许 Repository-controlled Code 执行的 Trust，并不等于允许它继承 Ambient Secret 的 Authority。</strong></p><h2 id="executable-configuration-就是-code" tabindex="-1">Executable Configuration 就是 Code <a class="header-anchor" href="#executable-configuration-就是-code" aria-label="Permalink to &quot;Executable Configuration 就是 Code&quot;">​</a></h2><p>Project <code>.mcp.json</code> 设计上可以通过 Version Control 共享。这有助于复现配置，也意味着 Clone 下来的 Repository 可以提出 Executable Behavior。Trust Gate 询问的是：来自这个 Folder 的 Code 是否可以运行。当前文档明确说明，Project 或 Local <code>headersHelper</code> 要等到 Workspace Trust 被接受后才能执行；Folder 未受信时，Clone 的 Repository 也不能通过自己的 Checked-in Setting 预先批准 Project Server。</p><p>这是 Code Admission，不是 Benign-code Certificate。用户可能信任后来发生变化的 Repository，Trusted Helper 也仍可能包含恶意或过宽 Shell Logic。Trust State 因而只为一个决定提供证据：Runtime 可以从解析配置跨越到执行所声明 Helper。</p><p>Origin 同样重要。Project File、Plugin、User Configuration 与 Managed Setting 有不同 Ownership 与 Review Path。记录 Source、Canonical Path、Trust State 与 Content Identity，可以让 Admission Decision 可归责，而不是把所有解析出的配置值视为等价。</p><h2 id="admission-与-capability-grant-需要分开门禁" tabindex="-1">Admission 与 Capability Grant 需要分开门禁 <a class="header-anchor" href="#admission-与-capability-grant-需要分开门禁" aria-label="Permalink to &quot;Admission 与 Capability Grant 需要分开门禁&quot;">​</a></h2><p>通过 Admission 后，Runtime 还必须决定 Child 获得什么 Authority。完整继承 Parent Environment 很方便，因为 Credential、Proxy 与 Provider Setting 会自动出现；但它也是 Accidental Delegation：Helper 获得 Secret，是因为 Launcher 恰好拥有，而不是因为任务明确需要。</p><p>v2.1.238 Note 描述了对选定 Helper Origin 移除 Inherited Credential Environment Variable。这是一项 Least-authority Control。Folder Trust 允许代码运行，Environment Policy 则扣留另一类 Capability。任何一项单独存在都不完整：Trust 而不 Sanitization，可能过度授权已接受 Helper；Sanitization 而不 Trust，仍可能执行未受信 Repository Code。</p><p>两类决定应独立评审，因为 Blast Radius 不同。Repository Identity 或 Helper Content 改变，可能让 Execution Trust 失效；Provider Secret 或 Helper 预期访问目标改变，则可能要求新的 Secret-access Decision，即使 Code Admission 仍然有效。</p><h2 id="用显式-context-取代-ambient-inheritance" tabindex="-1">用显式 Context 取代 Ambient Inheritance <a class="header-anchor" href="#用显式-context-取代-ambient-inheritance" aria-label="Permalink to &quot;用显式 Context 取代 Ambient Inheritance&quot;">​</a></h2><p>官方文档公开 <code>CLAUDE_CODE_MCP_SERVER_NAME</code>、<code>CLAUDE_CODE_MCP_SERVER_URL</code> 等 Purpose-specific Input，并在适用时提供额外 Plugin Context。这指向更强的 Child-process Contract：传入声明任务需要的 Context，再有意授予其他 Capability。</p><p>这样的契约可以描述：</p><ul><li>Executable Configuration 的 Origin 与 Content Identity；</li><li>允许执行的 Trusted Folder 或 Plugin Boundary；</li><li>提供给 Helper 的 Allowlisted Task Input；</li><li>分别授予的 Secret、Filesystem Location、Network Destination 与 External Effect。</li></ul><p>拒绝也必须 Fail-visible。如果 Sanitization 移除了 Helper 期待的 Credential，Runtime 应区分 <code>capability-denied</code>、Remote Authentication Failure、Network Failure 与 Malformed Helper Output。否则 Operator 可能在错误 Layer 上修复问题，反而扩大 Ambient Access。</p><p>并非每个 Helper 都需要重量级 Sandbox。用户控制仓库里的低风险本地命令，可能适合较粗的 Trust Boundary。原则不是不计成本地追求最大隔离，而是每项 Capability 都因任务需要而授予，而不是因为 Parent 恰好拥有。</p><h2 id="environment-filtering-不是-sandbox" tabindex="-1">Environment Filtering 不是 Sandbox <a class="header-anchor" href="#environment-filtering-不是-sandbox" aria-label="Permalink to &quot;Environment Filtering 不是 Sandbox&quot;">​</a></h2><p>公开证据支持 Credential-environment Filtering 的存在，却不支持其准确实现。所选公开 Commit 发布的是 Release Note，不是 Product Source；已读材料与文档都没有枚举被剥离 Variable List 或 Public Regression Matrix。Helper 仍可能收到 Non-credential Environment Value 与显式 Context。</p><p>更重要的是，Environment Filtering 只关闭一条 Authority Channel。Trusted Shell Helper 仍可能读取文件、访问网络、检查 Process-visible Resource，或使用 Host 允许的 Credential Store。这里没有公开证据建立 Filesystem、Network、Keychain、Process 或 External-effect Isolation。</p><p>这条边界定义了下一组设计问题：Helper 是否应在执行前声明 Required Capability？Provider 变化时 Credential Classification 如何维护？Repository Identity、Path Ownership 或 Helper Content 改变后，哪些 Trust Decision 必须失效？什么 Machine-readable Error 能告诉自动化系统 Authority 是被有意扣留，而不是偶然失败？</p><p>Workspace Trust 与 Credential Filtering 的价值，恰恰来自它们回答不同问题。前者决定 Executable Configuration 能否运行，后者限制 Admission 之后的一类 Authority。更强 Isolation 从保持这两类事实分离开始，也从没有额外 Evidence 时拒绝把任何一项称为 Sandbox 开始。</p><p><strong>一手证据：</strong> <a href="https://github.com/anthropics/claude-code/commit/8a8e81d098cbd0fae4ee5b9c853542945fe87016" target="_blank" rel="noreferrer">Claude Code Release 提交 8a8e81d</a> 与<a href="https://code.claude.com/docs/en/mcp" target="_blank" rel="noreferrer">官方 MCP 文档</a>。Release Note 是权威 Product Documentation，但没有公开私有 Filtering Implementation 或独立验证。</p>',24))])}const b=i(l,[["render",c]]);export{g as __pageData,b as default};
